export const biography = ["Antoine Martin est né en 1997 à Vitry-sur-Seine. Photographe indépendant depuis 2018, il développe des projets personnels et travaille pour la presse et les institutions.", "Formé au photojournalisme, il part en Ukraine au début de l’invasion de 2022. Cette expérience le conduit à chercher une écriture plus personnelle, à la rencontre du documentaire et du journalisme.", "Ses séjours à Miami donnent naissance à Miami, not the Beach. Il poursuit ensuite son travail à Port-au-Prince et photographie ses proches en France depuis 2017. Le flash lui permet de ralentir les prises de vue et de construire la lumière dans des lieux où il prend le temps de revenir."];

const covers={miami:11,haiti:13,jeunesse:7,chine:0,science:0,usa:0,centrafrique:9,senegal:0,commercial:0,portraits:0,portfolio:0};
for(const project of projects)project.cover=covers[project.id]??0;
